<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{Building,Customer,ImportBatch,Room}; use App\Services\AuditService; use Illuminate\Http\Request; use PhpOffice\PhpSpreadsheet\IOFactory;
class ImportController extends Controller {
 public function index(){return response()->json(ImportBatch::latest()->paginate(25));}
 public function store(Request $r){$d=$r->validate(['type'=>'required|in:buildings,rooms,customers','file'=>'required|file|mimes:csv,txt,xlsx,xls|max:10240']);$rows=IOFactory::load($d['file']->getRealPath())->getActiveSheet()->toArray();$headers=array_map(fn($v)=>strtolower(trim((string)$v)),array_shift($rows)?:[]);$errors=[];$success=0;foreach($rows as $i=>$values){$row=array_combine($headers,$values);try{$this->row($d['type'],$row,$r->user()->company_id);$success++;}catch(\Throwable $e){$errors[]=['row'=>$i+2,'message'=>$e->getMessage()];}}$batch=ImportBatch::create(['company_id'=>$r->user()->company_id,'uploaded_by'=>$r->user()->id,'type'=>$d['type'],'filename'=>$d['file']->getClientOriginalName(),'total_rows'=>count($rows),'successful_rows'=>$success,'failed_rows'=>count($errors),'errors'=>$errors,'status'=>$errors?($success?'completed_with_errors':'failed'):'completed']);AuditService::record('import.completed',$batch);return response()->json(['data'=>$batch],201);}
 private function row(string $type,array $r,int $cid):void{if($type==='buildings'){validator($r,['code'=>'required','name'=>'required'])->validate();Building::updateOrCreate(['company_id'=>$cid,'code'=>$r['code']],['name'=>$r['name'],'address'=>$r['address']??null,'is_active'=>true]);return;}$building=Building::where('code',$r['building_code']??'')->firstOrFail();if($type==='rooms'){validator($r,['number'=>'required','capacity'=>'required|integer|min:1'])->validate();Room::updateOrCreate(['company_id'=>$cid,'building_id'=>$building->id,'number'=>$r['number']],['capacity'=>$r['capacity'],'is_active'=>true]);return;}validator($r,['room_number'=>'required','customer_code'=>'required','name'=>'required','passport_number'=>'required','phone'=>'required'])->validate();$room=Room::where('building_id',$building->id)->where('number',$r['room_number'])->firstOrFail();abort_if(Customer::where('room_id',$room->id)->where('is_active',true)->count()>=$room->capacity,422,"Room {$room->number} is full");Customer::updateOrCreate(['company_id'=>$cid,'customer_code'=>$r['customer_code']],['building_id'=>$building->id,'room_id'=>$room->id,'name'=>$r['name'],'passport_number'=>$r['passport_number'],'phone'=>$r['phone'],'start_date'=>$r['start_date']??now()->toDateString(),'is_active'=>true]);}
}
